input.new_string:
    #[test]
    fn scrub_removes_home_paths() {
        let input = "Error at /home/user/project/file.rs:42";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[PATH]"));
        assert!(!scrubbed.contains("/home/user"));
    }

    #[test]
    fn scrub_removes_windows_paths() {
        let input = r"Error at C:\Users\brenna\project\main.rs";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[PATH]"));
        assert!(!scrubbed.contains(r"C:\Users\brenna"));
    }

    #[test]
    fn scrub_removes_tmp_paths() {
        let input = "Error at /tmp/build-abc123/output.log";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[PATH]"));
        assert!(!scrubbed.contains("/tmp/build"));
    }

    #[test]
    fn scrub_removes_slack_xoxb_tokens() {
        let input = "token: xoxb-1234-abcdef-ghijkl";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("xoxb-"));
    }

    #[test]
    fn scrub_removes_slack_xoxp_tokens() {
        let input = "token: xoxp-9876-zyxwvu-tsrqpo";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("xoxp-"));
    }

    #[test]
    fn scrub_removes_gho_tokens() {
        let input = "oauth: gho_abcdefghijklmnopqrstuvwxyz1234567890";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(scrubbed.contains("[REDACTED]"));
        assert!(!scrubbed.contains("gho_"));
    }

    #[test]
    fn scrub_handles_empty_input() {
        let scrubbed = scrub_for_telemetry("", &HashMap::new());
        assert_eq!(scrubbed, "");
    }

    #[test]
    fn scrub_handles_empty_env() {
        let input = "safe text only";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert_eq!(scrubbed, "safe text only");
    }

    #[test]
    fn scrub_skips_empty_env_values() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "".to_string());

        let input = "nothing to mask here";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert_eq!(scrubbed, "nothing to mask here");
    }

    #[test]
    fn scrub_handles_multiple_sensitive_types_combined() {
        let mut env = HashMap::new();
        env.insert("DB_PASSWORD".to_string(), "s3cret".to_string());

        let input = "Error at /Users/dev/app: auth failed with s3cret and ghp_abcdefghijklmnopqrstuvwxyz1234567890";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert!(!scrubbed.contains("s3cret"));
        assert!(!scrubbed.contains("/Users/dev"));
        assert!(!scrubbed.contains("ghp_"));
    }

    #[test]
    fn scrub_non_secret_env_vars_not_masked() {
        let mut env = HashMap::new();
        env.insert("PATH".to_string(), "/usr/bin".to_string());
        env.insert("NODE_ENV".to_string(), "production".to_string());

        let input = "NODE_ENV=production";
        let scrubbed = scrub_for_telemetry(input, &env);
        assert!(scrubbed.contains("production"));
    }

    #[test]
    fn scrub_truncation_boundary() {
        // Exactly at the limit should not truncate
        let input = "x".repeat(MAX_ERROR_LENGTH);
        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
        assert_eq!(scrubbed.len(), MAX_ERROR_LENGTH);
        assert!(!scrubbed.contains("[truncated]"));
    }

    #[test]
    fn scrub_truncation_one_over() {
        let input = "x".repeat(MAX_ERROR_LENGTH + 1);
        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
        assert!(scrubbed.ends_with("...[truncated]"));
    }

    #[test]
    fn telemetry_consent_display() {
        assert_eq!(TelemetryConsent::Send.to_string(), "send");
        assert_eq!(TelemetryConsent::NoThanks.to_string(), "no_thanks");
        assert_eq!(TelemetryConsent::Always.to_string(), "always");
        assert_eq!(TelemetryConsent::Never.to_string(), "never");
    }

    #[test]
    fn telemetry_prompt_returns_always_from_user() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "always");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Always);
        assert_eq!(ui.prompts_shown(), &["telemetry_failure"]);
    }

    #[test]
    fn telemetry_prompt_returns_never_from_user() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "never");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Never);
    }

    #[test]
    fn telemetry_prompt_unknown_response_defaults_to_no_thanks() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "garbage");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::NoThanks);
    }

    #[test]
    fn telemetry_prompt_unrecognized_saved_pref_still_prompts() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "send");

        let result = prompt_telemetry(&mut ui, &report, Some("unknown_pref")).unwrap();
        assert_eq!(result, TelemetryConsent::Send);
        // A prompt should have been shown because "unknown_pref" isn't "always" or "never"
        assert_eq!(ui.prompts_shown().len(), 1);
    }

    #[test]
    fn telemetry_prompt_shows_step_name_in_messages() {
        let report = build_report(
            "bundler",
            "bundle install",
            Some(1),
            "gem error",
            "retry",
            &HashMap::new(),
        );
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        assert!(ui.has_message("bundler"));
        assert!(ui.has_message("bundle install"));
        assert!(ui.has_message("gem error"));
        assert!(ui.has_message("retry"));
    }

    #[test]
    fn telemetry_prompt_shows_exit_code_when_present() {
        let report = build_report("test", "cmd", Some(42), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        assert!(ui.has_message("42"));
    }

    #[test]
    fn telemetry_prompt_omits_exit_code_when_none() {
        let report = build_report("test", "cmd", None, "err", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        // Should not contain "Exit:" line
        assert!(!ui.messages().iter().any(|m| m.contains("Exit:")));
    }

    #[test]
    fn telemetry_prompt_omits_error_when_empty() {
        let report = build_report("test", "cmd", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        // Should not contain "Error:" line
        assert!(!ui.messages().iter().any(|m| m.contains("Error:")));
    }

    #[test]
    fn build_report_with_none_exit_code() {
        let report = build_report(
            "test",
            "killed_cmd",
            None,
            "signal terminated",
            "skip",
            &HashMap::new(),
        );

        assert_eq!(report.exit_code, None);
        assert_eq!(report.recovery_action, "skip");
    }

    #[test]
    fn build_report_scrubs_command() {
        let mut env = HashMap::new();
        env.insert("API_KEY".to_string(), "mysecretkey123".to_string());

        let report = build_report(
            "deploy",
            "curl -H 'Authorization: mysecretkey123'",
            Some(1),
            "",
            "retry",
            &env,
        );

        assert!(!report.command_scrubbed.contains("mysecretkey123"));
    }

    #[test]
    fn build_report_platform_has_os_and_arch() {
        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());

        assert!(report.platform.contains('-'));
        let parts: Vec<&str> = report.platform.split('-').collect();
        assert_eq!(parts.len(), 2);
        assert!(!parts[0].is_empty());
        assert!(!parts[1].is_empty());
    }

    #[test]
    fn failure_report_serialize_deserialize_roundtrip() {
        let report = FailureReport {
            step_name: "bundler".to_string(),
            command_scrubbed: "bundle install".to_string(),
            exit_code: Some(1),
            error_scrubbed: "gem build error".to_string(),
            recovery_action: "retry".to_string(),
            bivvy_version: "1.0.0".to_string(),
            platform: "macos-aarch64".to_string(),
        };

        let yaml = serde_yaml::to_string(&report).unwrap();
        let deserialized: FailureReport = serde_yaml::from_str(&yaml).unwrap();

        assert_eq!(deserialized.step_name, report.step_name);
        assert_eq!(deserialized.command_scrubbed, report.command_scrubbed);
        assert_eq!(deserialized.exit_code, report.exit_code);
        assert_eq!(deserialized.error_scrubbed, report.error_scrubbed);
        assert_eq!(deserialized.recovery_action, report.recovery_action);
        assert_eq!(deserialized.bivvy_version, report.bivvy_version);
        assert_eq!(deserialized.platform, report.platform);
    }

    #[test]
    fn failure_report_roundtrip_none_exit_code() {
        let report = FailureReport {
            step_name: "test".to_string(),
            command_scrubbed: "cmd".to_string(),
            exit_code: None,
            error_scrubbed: "".to_string(),
            recovery_action: "skip".to_string(),
            bivvy_version: "1.0.0".to_string(),
            platform: "linux-x86_64".to_string(),
        };

        let yaml = serde_yaml::to_string(&report).unwrap();
        let deserialized: FailureReport = serde_yaml::from_str(&yaml).unwrap();

        assert_eq!(deserialized.exit_code, None);
    }

    #[test]
    fn save_report_creates_directory() {
        let temp = tempfile::TempDir::new().unwrap();
        let nested = temp.path().join("nested").join("dir");
        assert!(!nested.exists());

        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());
        let path = save_report_to(&report, &nested).unwrap();

        assert!(nested.exists());
        assert!(path.exists());
    }

    #[test]
    fn save_report_filename_contains_step_name() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report("bundler", "bundle install", Some(1), "", "retry", &HashMap::new());

        let path = save_report_to(&report, temp.path()).unwrap();

        let filename = path.file_name().unwrap().to_str().unwrap();
        assert!(filename.ends_with("-bundler.yml"), "Expected filename ending with -bundler.yml, got: {}", filename);
    }

    #[test]
    fn save_report_content_deserializes_back() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report(
            "cargo",
            "cargo build",
            Some(101),
            "compile error",
            "shell → retry",
            &HashMap::new(),
        );

        let path = save_report_to(&report, temp.path()).unwrap();
        let content = std::fs::read_to_string(&path).unwrap();
        let loaded: FailureReport = serde_yaml::from_str(&content).unwrap();

        assert_eq!(loaded.step_name, "cargo");
        assert_eq!(loaded.command_scrubbed, "cargo build");
        assert_eq!(loaded.exit_code, Some(101));
        assert_eq!(loaded.error_scrubbed, "compile error");
        assert_eq!(loaded.recovery_action, "shell → retry");
    }

    #[test]
    fn save_report_multiple_reports_coexist() {
        let temp = tempfile::TempDir::new().unwrap();
        let report1 = build_report("step1", "cmd1", Some(1), "", "retry", &HashMap::new());
        let report2 = build_report("step2", "cmd2", Some(2), "", "skip", &HashMap::new());

        let path1 = save_report_to(&report1, temp.path()).unwrap();
        let path2 = save_report_to(&report2, temp.path()).unwrap();

        assert!(path1.exists());
        assert!(path2.exists());
        assert_ne!(path1, path2);
    }

    #[test]
    fn reports_dir_is_under_bivvy() {
        let dir = reports_dir();
        let dir_str = dir.to_string_lossy();
        assert!(
            dir_str.contains(".bivvy") && dir_str.contains("failure-reports"),
            "Expected path containing .bivvy/failure-reports, got: {}",
            dir_str
        );
    }
}

